import{_ as a,o as n,c as t,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Raids and paid incidents","description":"","frontmatter":{"pageId":"players/raids-incidents","contentRevision":2},"headers":[],"relativePath":"en/players/raids-incidents.md","filePath":"en/players/raids-incidents.md"}'),i={name:"en/players/raids-incidents.md"};function s(o,e,d,l,c,p){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="raids-and-paid-incidents" tabindex="-1">Raids and paid incidents <a class="header-anchor" href="#raids-and-paid-incidents" aria-label="Permalink to &quot;Raids and paid incidents&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Before raiding, choose a target, pawns and mode. Snapshot mode uses copies; real mode risks actual pawns. Review the confirmation, defender warning and loot rules. Warned raids give preparation time (60,000 ticks by default); instant raids halve the allowed loot.</p><p>Paid incidents are ordered from the server&#39;s available catalog. Price and warning depend on kind and intensity. The server checks peaceful mode, alliance membership, newcomer protection, cooldown and the target queue. Cancellation and refusals settle through escrow, not manual duplicate grants.</p><p>Inspect operation results and mail afterward: returning your own pawns and permitted loot is not the same as keeping an arbitrary map-copy save.</p><h2 id="raid-choice" tabindex="-1">How do I choose raid risk before dispatch? <a class="header-anchor" href="#raid-choice" aria-label="Permalink to &quot;How do I choose raid risk before dispatch? {#raid-choice}&quot;">​</a></h2><p>At a foreign settlement, choose a raid with a caravan/pods and select participants. <strong>Real</strong> removes actual pawns: survivors return wounded with inventory, captives stay with the defender. <strong>Copies</strong> keeps originals home but reduces loot. <strong>Warned</strong> gives the defender one game day to prepare; <strong>Instant</strong> reduces loot. Target wealth and server caps further limit allowed loot.</p><p>The defender&#39;s own game processes an ordinary raid when they play; simultaneous online presence is unnecessary. Inspect the Raids tab and resulting mail. Equipment carried by real raiders is not capped loot; copy equipment does not become real returned items.</p><p>Peaceful mode blocks attacks both ways. Disabling it takes 24 hours by default; rechecking keeps protection. Newcomer, low-wealth and alliance protection are separate rules. Chat blocking grants none of these.</p><h2 id="incident-order" tabindex="-1">Paid incidents: ordering, unknown responses and refunds <a class="header-anchor" href="#incident-order" aria-label="Permalink to &quot;Paid incidents: ordering, unknown responses and refunds {#incident-order}&quot;">​</a></h2><p>Open economy → <strong>Events</strong>: select target, catalog entry, level and pods where offered. Review the server quote, then confirm. Hostile levels use half/normal/one-and-a-half/double base threat points. Hostile levels 3–4 warn half a game day ahead.</p><p>Hostile/weather incidents obey raid protection and cooldowns; friendly entries have a separate short cooldown. Default target queue is two events. If an incident cannot run, expires before the target plays, or is cancelled by an administrator, payment is refunded. A successful event does not pay its target.</p><p>For an unknown response, use <strong>Retry original order</strong>. Do not change target or purchase again until persisted intent resolves. <strong>My orders</strong> shows outcomes; an awaiting hostile incident also blocks goods export.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Defaults: 10 raiders, 1 active raid, 8-hour cooldown and 24 hours per pair, 3-day newcomer protection, minimum wealth 20,000, loot 10% capped at 5,000, kidnapping disabled. Leaving peaceful mode takes 24 hours. Allies cannot order harmful incidents against each other.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./live">Live: the active map</a></li><li><a href="./visits">Visits and shops</a></li><li><a href="./../admins/gameplay-policy">Server gameplay policy</a></li></ul>',18)])])}const m=a(i,[["render",s]]);export{u as __pageData,m as default};
